 $('#googleLogin').onclick=async()=>{const btn=$('#googleLogin');btn.disabled=true;try{await Cloud.google();await finish();}catch(e){$('#authError').textContent=errorText(e);btn.disabled=false;}};
 $('#authForm').onsubmit=async e=>{e.preventDefault();const btn=$('#authSubmit');btn.disabled=true;$('#authError').textContent='Connecting…';try{await Cloud.login($('#email').value.trim(),$('#password').value,authMode==='signup');await finish();}catch(err){$('#authError').textContent=errorText(err);btn.disabled=false;}};
